import test from 'node:test';import assert from 'node:assert/strict';import {makeBriefPreferencesRecord} from '../src/dev-preferences-model.mjs';import {createPrivateSessionHttp} from '../server/private-workspace-session-http.mjs';
const origin='http://127.0.0.1:5312',owner='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
async function call(router,path,{method='GET',headers={},body={},bodyReader}={}){const req={url:path,method,headers:{host:'127.0.0.1:5312',...headers},[Symbol.asyncIterator]:bodyReader||async function*(){yield JSON.stringify(body);}},res={writeHead(status,headers){this.status=status;this.headers=headers;return this;},end(value){this.body=value;}};assert.equal(await router.handle(req,res),true);return res;}
async function setup(t,options={}){const state={active:true,closed:[],logins:0},api={signIn:async()=>{state.logins++;return{accessToken:'FICTIONAL_ACCESS_SECRET',refreshToken:'FICTIONAL_REFRESH_SECRET',expiresAt:Date.now()+3600000};},getUser:async()=>({id:owner,email:'fictional@example.test'}),isSessionActive:async()=>state.active,refreshSession:async()=>{throw Error('not expected');},signOutLocal:async token=>state.closed.push(token),listPrivateProjects:async()=>[],getPrivateProject:async()=>[],addPrivateProject:async()=>{throw Error('Unexpected project write');},updatePrivateProject:async()=>{throw Error('Unexpected project edit');},listBriefPreferences:async()=>[],listPrivateBriefRecords:async()=>[],listSavedMailMetadata:async()=>[],getPrivateRecordState:async()=>[],listPrivateDeletedRecords:async()=>[],setPrivateRecordDeletedAt:async()=>{throw Error('Unexpected recovery write');},listPrivateAppearance:async()=>[],addNote:async()=>{throw Error('Unexpected note insert');},getPrivateEvent:async()=>[],updatePrivateEvent:async()=>{throw Error('Unexpected event edit');},addFictionalEvent:async()=>{throw Error('Unexpected event creation');},addFictionalTask:async()=>{throw Error('Unexpected task insert');},getPrivateTaskDetails:async()=>[],getPrivateTask:async()=>[],updatePrivateTask:async()=>{throw Error('Unexpected task edit');},reopenPrivateTask:async()=>{throw Error('Unexpected reopening');},completePrivateTask:async()=>{throw Error('Unexpected completion');},getPrivateNote:async()=>{throw Error('Unexpected note read');},getPrivateNoteForEdit:async()=>{throw Error('Unexpected edit read');},updatePrivateNote:async()=>{throw Error('Unexpected note write');},updateBriefPreferences:async()=>{throw Error('Unexpected write');},addBriefPreferences:async()=>{throw Error('Unexpected insert');}},router=createPrivateSessionHttp({origin,api,ui:'<h1>Fictional sign-in</h1>',script:'// fictional',css:'body{}',...options});t.after(()=>router.dispose());const bootstrap=await call(router,'/auth/workspace/status'),cookie=bootstrap.headers['Set-Cookie'].split(';')[0],csrf=JSON.parse(bootstrap.body).csrf;return{router,state,api,cookie,csrf,headers:{origin,cookie,'content-type':'application/json','x-cc-request':'workspace-session','x-cc-csrf':csrf}};}
test('browser bootstrap cookie is HttpOnly, Strict, scoped, bounded and absent from response JSON',async t=>{const s=await setup(t),status=await call(s.router,'/auth/workspace/status',{headers:{cookie:s.cookie}});assert.match(status.headers['Set-Cookie'],/HttpOnly; SameSite=Strict; Path=\/auth\/workspace; Max-Age=\d+/);assert.doesNotMatch(status.headers['Set-Cookie'],/Domain=/);assert.equal(status.headers['Cache-Control'],'no-store');assert.equal(JSON.parse(status.body).signedIn,false);assert.doesNotMatch(status.body,/cc_workspace_preview|sessionId|FICTIONAL_/);assert.equal(status.headers['X-Frame-Options'],'DENY');});
test('login returns safe metadata and keeps upstream credentials and vault handle out of the browser',async t=>{const s=await setup(t),login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'FICTIONAL_PASSWORD'}});assert.equal(login.status,200);assert.equal(JSON.parse(login.body).signedIn,true);assert.doesNotMatch(login.body,/FICTIONAL_|sessionId|refreshToken|accessToken/);const status=await call(s.router,'/auth/workspace/status',{headers:{cookie:s.cookie}});assert.equal(JSON.parse(status.body).user.id,owner);});
test('cross-origin, rebound hosts, cross-site status and missing or wrong CSRF requests are rejected before login',async t=>{const s=await setup(t);for(const headers of [{...s.headers,origin:'https://evil.test'},{...s.headers,host:'evil.test'},{...s.headers,'x-cc-csrf':'invalid'},{...s.headers,'x-cc-request':undefined},{...s.headers,'content-type':'text/plain'}])assert.equal((await call(s.router,'/auth/workspace/login',{method:'POST',headers,body:{email:'fixture',password:'fixture'}})).status,403);assert.equal((await call(s.router,'/auth/workspace/status',{headers:{'sec-fetch-site':'cross-site'}})).status,403);assert.equal(s.state.logins,0);});
test('logout clears the cookie, revokes its upstream login and invalidates the old browser context',async t=>{const s=await setup(t),login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body);const logout=await call(s.router,'/auth/workspace/logout',{method:'POST',headers:{...s.headers,'x-cc-csrf':login.csrf}});assert.equal(logout.status,200);assert.equal(JSON.parse(logout.body).remoteRevoked,true);assert.match(logout.headers['Set-Cookie'],/Max-Age=0/);assert.equal(s.state.closed.length,1);assert.equal((await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers})).status,403);});
test('logout during a pending login cancels the response cookie and closes the late upstream login',async t=>{const s=await setup(t);let release,started=false;s.api.signIn=()=>{started=true;return new Promise(resolve=>release=resolve);};const pending=call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});while(!started)await new Promise(resolve=>setImmediate(resolve));assert.equal((await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers})).status,200);release({accessToken:'FICTIONAL_LATE',refreshToken:'FICTIONAL_REFRESH',expiresAt:Date.now()+3600000});const result=await pending;assert.equal(result.status,409);assert.equal(result.headers['Set-Cookie'],undefined);assert.ok(s.state.closed.includes('FICTIONAL_LATE'));});
test('cancel remains valid after login completes but before its response updates the browser request state',async t=>{const s=await setup(t);const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal(login.status,200);const cancelled=await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});assert.equal(cancelled.status,200);assert.equal(JSON.parse(cancelled.body).remoteRevoked,true);assert.match(cancelled.headers['Set-Cookie'],/Max-Age=0/);});
test('logout while login body is pending prevents even starting the upstream authentication request',async t=>{const s=await setup(t);let release;const gate=new Promise(resolve=>release=resolve),pending=call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,bodyReader:async function*(){await gate;yield JSON.stringify({email:'fixture',password:'fixture'});}});await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release();assert.equal((await pending).status,409);assert.equal(s.state.logins,0);});
test('revocation clears authenticated status; account changes require explicit sign-out',async t=>{const s=await setup(t);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const status=JSON.parse((await call(s.router,'/auth/workspace/status',{headers:{cookie:s.cookie}})).body);assert.equal((await call(s.router,'/auth/workspace/login',{method:'POST',headers:{...s.headers,'x-cc-csrf':status.csrf},body:{email:'other@example.test',password:'fixture'}})).status,409);s.state.active=false;const revoked=await call(s.router,'/auth/workspace/status',{headers:{cookie:s.cookie}});assert.equal(revoked.status,401);assert.doesNotMatch(revoked.body,/fictional@example/);assert.match(revoked.headers['Set-Cookie'],/Max-Age=0/);});
test('there are no record, arbitrary proxy or credential-file endpoints',async t=>{const s=await setup(t);for(const path of ['/auth/workspace/records','/auth/workspace/proxy','/auth/workspace/.env.local'])assert.equal((await call(s.router,path,{headers:{cookie:s.cookie}})).status,404);});

async function signedPreferences(t){const s=await setup(t,{allowPreferencesRead:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});return s;}
test('preferences are opt-in, authenticated, read only and whitelisted without raw record/credential fields',async t=>{const s=await signedPreferences(t);let reads=0;s.api.listBriefPreferences=async(token,ownerId)=>{reads++;assert.equal(token,'FICTIONAL_ACCESS_SECRET');assert.equal(ownerId,owner);return[{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal'},owner),payload:{...makeBriefPreferencesRecord({palette:'coastal'},owner).payload,accessToken:'FICTIONAL_PAYLOAD_SECRET'}}];};const result=await call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});assert.equal(result.status,200);const data=JSON.parse(result.body);assert.equal(data.preferences.palette,'coastal');assert.equal(data.hasSavedPreferences,true);assert.equal(data.readOnly,true);assert.equal(reads,1);assert.doesNotMatch(result.body,/FICTIONAL_|bbbbbbbb|owner_id|payload|refreshToken/);assert.equal((await call(s.router,'/auth/workspace/preferences',{method:'POST',headers:s.headers})).status,404);});
test('anonymous settings requests do not touch the data API and disabled transport has no settings route',async t=>{const s=await setup(t,{allowPreferencesRead:true});let reads=0;s.api.listBriefPreferences=async()=>{reads++;return[];};assert.equal((await call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}})).status,401);assert.equal(reads,0);const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/preferences')).status,404);});
test('foreign, shared or deleted settings responses fail closed instead of displaying false account defaults',async t=>{const s=await signedPreferences(t),base={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal'},owner)};for(const change of [{owner_id:'cccccccc-cccc-4ccc-8ccc-cccccccccccc'},{visibility:'household',household_id:owner},{deleted_at:'2026-11-09T12:00:00Z'}]){s.api.listBriefPreferences=async()=>[{...base,...change}];const result=await call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});assert.equal(result.status,503);assert.doesNotMatch(result.body,/coastal|bbbbbbbb|cccccccc/);}});
test('sign-out during a settings read suppresses the late private response',async t=>{const s=await signedPreferences(t);let release;s.api.listBriefPreferences=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'blush'},owner)}]);const result=await pending;assert.notEqual(result.status,200);assert.doesNotMatch(result.body,/blush|preferences|bbbbbbbb/);});
test('upstream revocation during a settings read withholds the result',async t=>{const s=await signedPreferences(t);s.api.listBriefPreferences=async()=>{s.state.active=false;return[];};const result=await call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});assert.equal(result.status,503);assert.doesNotMatch(result.body,/neutral|quietHours/);});

async function writeSetup(t,options={}){const s=await setup(t,{allowPreferencesRead:true,allowPreferencesSave:true,...options});s.state.current={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal',navigation:{order:['school'],hidden:['home']}},owner)};s.state.current.payload.futureField='preserved';s.state.writes=0;s.api.listBriefPreferences=async()=>s.state.current?[structuredClone(s.state.current)]:[];s.api.updateBriefPreferences=async(_token,record,_owner,payload)=>{s.state.writes++;if(!s.state.current||record.version!==s.state.current.version)return[];s.state.current={...s.state.current,version:s.state.current.version+1,payload:structuredClone(payload)};return[structuredClone(s.state.current)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.latest=()=>call(s.router,'/auth/workspace/preferences',{headers:{cookie:s.cookie}});s.review=async()=>{const current=JSON.parse((await s.latest()).body);return call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:{palette:'blush',density:'compact',hideAmounts:true}}});};s.save=id=>call(s.router,'/auth/workspace/preferences/save',{method:'POST',headers:s.headers,body:{reviewId:id,approved:true}});return s;}
test('settings review is non-writing and a single approved save preserves unrelated preferences and extension fields',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);assert.ok(review.reviewId);assert.equal(s.state.writes,0);const saved=await s.save(review.reviewId);assert.equal(saved.status,200);assert.equal(JSON.parse(saved.body).saved,true);assert.equal(s.state.writes,1);assert.equal(s.state.current.payload.palette,'blush');assert.equal(s.state.current.payload.futureField,'preserved');assert.equal(s.state.current.payload.navigation.order[0],'school');assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,1);assert.doesNotMatch(saved.body,/futureField|bbbbbbbb|FICTIONAL_/);});
test('stale, deleted or expired settings reviews cannot start a write',async t=>{for(const mode of ['changed','deleted','expired']){let clock=1;const s=await writeSetup(t,{now:()=>clock}),review=JSON.parse((await s.review()).body);if(mode==='changed')s.state.current.version++;if(mode==='deleted')s.state.current=null;if(mode==='expired')clock+=300001;assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,0);}});
test('two simultaneous approval requests produce only one settings write',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body),results=await Promise.all([s.save(review.reviewId),s.save(review.reviewId)]);assert.deepEqual(results.map(row=>row.status).sort(),[200,409]);assert.equal(s.state.writes,1);});
test('lost write acknowledgement consumes the review and cannot silently retry',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);s.api.updateBriefPreferences=async()=>{s.state.writes++;throw Error('Fictional lost acknowledgement');};const result=await s.save(review.reviewId);assert.equal(result.status,503);assert.match(result.body,/may have completed/);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,1);});
test('sign-out during settings save authorization prevents the mutation',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);let release;s.api.listBriefPreferences=()=>new Promise(resolve=>release=resolve);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([structuredClone(s.state.current)]);assert.notEqual((await pending).status,200);assert.equal(s.state.writes,0);});
test('wrong acknowledgement content never produces a save success',async t=>{const s=await writeSetup(t),review=JSON.parse((await s.review()).body);s.api.updateBriefPreferences=async()=>{s.state.writes++;return[{...s.state.current,version:2}];};assert.equal((await s.save(review.reviewId)).status,503);assert.equal(s.state.writes,1);});
test('a settings review cannot inject navigation, source permissions or arbitrary record fields',async t=>{const s=await writeSetup(t),baseTag=JSON.parse((await s.latest()).body).baseTag;for(const changes of [{palette:'blush',density:'compact',hideAmounts:true,navigation:{hidden:[]}},{palette:'unknown',density:'compact',hideAmounts:true},{palette:'blush',density:'compact',hideAmounts:'false'}])assert.equal((await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag,changes}})).status,409);assert.equal(s.state.writes,0);});
test('saving first default preferences requires review and approval, then returns a verified saved copy',async t=>{const s=await writeSetup(t);s.state.current=null;s.api.addBriefPreferences=async(_token,row)=>{s.state.writes++;s.state.current={...structuredClone(row),id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null};return[structuredClone(s.state.current)];};const current=JSON.parse((await s.latest()).body),review=await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:{palette:current.preferences.palette,density:current.preferences.density,hideAmounts:current.preferences.hideAmounts}}});assert.equal(JSON.parse(review.body).createsPreferences,true);assert.equal(s.state.writes,0);assert.equal((await s.save(JSON.parse(review.body).reviewId)).status,200);assert.equal(s.state.writes,1);});
test('reviewing unchanged saved settings produces no writable review or unnecessary update',async t=>{const s=await writeSetup(t),current=JSON.parse((await s.latest()).body),result=await call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:{palette:current.preferences.palette,density:current.preferences.density,hideAmounts:current.preferences.hideAmounts}}});assert.equal(JSON.parse(result.body).noChanges,true);assert.equal(JSON.parse(result.body).reviewId,undefined);assert.equal(s.state.writes,0);});

async function briefSetup(t){const s=await setup(t,{allowBriefRead:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.state.briefRow={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',deleted_at:null,created_at:'2026-11-09T12:00:00Z',payload:{fictional:true,title:'Fictional private title',body:'NEVER_RETURN_THIS_BODY'}};s.api.listPrivateBriefRecords=async(token,ownerId)=>{assert.equal(token,'FICTIONAL_ACCESS_SECRET');assert.equal(ownerId,owner);return[structuredClone(s.state.briefRow)];};return s;}
test('private workspace brief is explicit, authenticated and read only with whitelisted display fields',async t=>{const s=await briefSetup(t),result=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(result.status,200);const data=JSON.parse(result.body);assert.equal(data.counts.notes,1);assert.equal(data.notes[0].title,'Fictional private title');assert.equal(data.readOnly,true);assert.doesNotMatch(result.body,/NEVER_RETURN|FICTIONAL_ACCESS|bbbbbbbb|owner_id/);assert.equal((await call(s.router,'/auth/workspace/brief',{method:'POST',headers:s.headers})).status,404);const disabled=await setup(t);assert.equal((await call(disabled.router,'/auth/workspace/brief')).status,404);});
test('anonymous and cross-site brief requests cannot start workspace reads',async t=>{const s=await setup(t,{allowBriefRead:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[];};assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).status,401);assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie,origin:'https://other.test'}})).status,403);assert.equal(reads,0);});
test('logout during a private brief read suppresses late record titles',async t=>{const s=await briefSetup(t);let release;s.api.listPrivateBriefRecords=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.state.briefRow]);const result=await pending;assert.equal(result.status,503);assert.doesNotMatch(result.body,/Fictional private|NEVER_RETURN/);});
test('foreign brief data and upstream revocation fail closed instead of exposing a partial view',async t=>{for(const mode of ['foreign','revoked']){const s=await briefSetup(t);s.api.listPrivateBriefRecords=async()=>{if(mode==='revoked')s.state.active=false;return[{...s.state.briefRow,...(mode==='foreign'?{owner_id:'cccccccc-cccc-4ccc-8ccc-cccccccccccc'}:{})}];};const result=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(result.status,503);assert.doesNotMatch(result.body,/Fictional private|NEVER_RETURN|cccccccc/);}});

async function noteSetup(t,options={}){const s=await setup(t,{allowBriefRead:true,allowNoteRead:true,...options});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',deleted_at:null,created_at:'2026-11-09T12:00:00Z',payload:{fictional:true,title:'Fictional note',body:'PRIVATE_FICTIONAL_BODY'}};s.reads=0;s.api.listPrivateBriefRecords=async()=>[s.row];s.api.getPrivateNote=async()=>{s.reads++;return[s.row];};s.list=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});s.open=noteToken=>call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:s.headers,body:{noteToken}});return s;}
test('private note text is default-off and not read until an authenticated selected-note request',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/notes/read',{method:'POST',headers:off.headers})).status,404);const s=await noteSetup(t),brief=await s.list();assert.equal(s.reads,0);assert.doesNotMatch(brief.body,/PRIVATE_FICTIONAL_BODY/);const token=JSON.parse(brief.body).notes[0].noteToken,result=await s.open(token);assert.equal(result.status,200);assert.equal(JSON.parse(result.body).body,'PRIVATE_FICTIONAL_BODY');assert.equal(s.reads,1);assert.doesNotMatch(result.body,/bbbbbbbb|owner_id|payload/);});
test('selected-note requests require CSRF and reject arbitrary record IDs',async t=>{const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;assert.equal((await call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:{...s.headers,'x-cc-csrf':'invalid'},body:{noteToken:token}})).status,403);assert.equal((await call(s.router,'/auth/workspace/notes/read',{method:'POST',headers:s.headers,body:{noteToken:token,id:s.row.id}})).status,409);assert.equal(s.reads,0);});
test('sign-out or upstream revocation during note retrieval withholds text',async t=>{for(const mode of ['logout','revoked']){const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;let release;s.api.getPrivateNote=()=>new Promise(resolve=>release=resolve);const pending=s.open(token);while(!release)await new Promise(resolve=>setImmediate(resolve));if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else s.state.active=false;release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_FICTIONAL_BODY/);}});

test('a fresh brief during final note-session verification suppresses the previous selected note',async t=>{const s=await noteSetup(t),token=JSON.parse((await s.list()).body).notes[0].noteToken;let release,gate=false;const verify=s.api.isSessionActive;s.api.getPrivateNote=async()=>{gate=true;return[s.row];};s.api.isSessionActive=async(...args)=>gate?new Promise(resolve=>release=resolve):verify(...args);const pending=s.open(token);while(!release)await new Promise(resolve=>setImmediate(resolve));gate=false;const refresh=s.list();release(true);await refresh;const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_FICTIONAL_BODY/);});

async function noteEditSetup(t){const s=await noteSetup(t,{allowNoteEdit:true});s.row.payload.extension='preserve';s.writes=0;s.api.getPrivateNoteForEdit=async()=>[structuredClone(s.row)];s.api.updatePrivateNote=async(_token,record,_owner,payload)=>{s.writes++;if(record.version!==s.row.version)return[];s.row={...s.row,version:s.row.version+1,payload:structuredClone(payload)};return[structuredClone(s.row)];};const token=JSON.parse((await s.list()).body).notes[0].noteToken;s.prepare=()=>call(s.router,'/auth/workspace/notes/review',{method:'POST',headers:s.headers,body:{noteToken:token,title:'Edited fictional note',body:'Edited fictional text'}});s.save=reviewId=>call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:s.headers,body:{reviewId,approved:true}});return s;}
test('note saves require opt-in and explicit one-use approval, preserving unrelated fields',async t=>{const off=await noteSetup(t);assert.equal((await call(off.router,'/auth/workspace/notes/save',{method:'POST',headers:off.headers})).status,404);const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);assert.equal(s.writes,0);assert.equal((await call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:s.headers,body:{reviewId:review.reviewId,approved:false}})).status,409);const results=await Promise.all([s.save(review.reviewId),s.save(review.reviewId)]);assert.deepEqual(results.map(row=>row.status).sort(),[200,409]);assert.equal(s.writes,1);assert.equal(s.row.payload.extension,'preserve');assert.equal(s.row.payload.body,'Edited fictional text');});
test('note review rejects injected record fields and saving requires request protection',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);assert.equal((await call(s.router,'/auth/workspace/notes/save',{method:'POST',headers:{...s.headers,'x-cc-csrf':'invalid'},body:{reviewId:review.reviewId,approved:true}})).status,403);assert.equal((await call(s.router,'/auth/workspace/notes/review',{method:'POST',headers:s.headers,body:{noteToken:'x'.repeat(43),title:'Fictional',body:'text',owner_id:owner}})).status,409);assert.equal(s.writes,0);});
test('logout during note save preflight prevents writes',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);let release;s.api.getPrivateNoteForEdit=()=>new Promise(resolve=>release=resolve);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);assert.equal((await pending).status,409);assert.equal(s.writes,0);});
test('an uncertain note save is not retried and a new brief invalidates old reviews',async t=>{const s=await noteEditSetup(t),review=JSON.parse((await s.prepare()).body);s.api.updatePrivateNote=async()=>{s.writes++;throw Error('Lost acknowledgement');};assert.equal((await s.save(review.reviewId)).status,503);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.writes,1);const refreshed=await s.list();assert.equal(refreshed.status,200);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.writes,1);});

async function creationSetup(t){const s=await setup(t,{allowBriefRead:true,allowTaskCreate:true});s.writes=0;s.row=null;s.api.addFictionalTask=async(_token,record)=>{s.writes++;s.row={...structuredClone(record),version:1,deleted_at:null};return[structuredClone(s.row)];};s.api.getPrivateTask=async()=>s.row?[structuredClone(s.row)]:[];await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.prepare=()=>call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:{title:'Fictional created task',day:'2026-11-09',section:'Home'}});s.save=reviewId=>call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId,approved:true}});return s;}
test('task creation is default-off; review is non-writing and repeated approval inserts once',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:off.headers})).status,404);const s=await creationSetup(t),review=JSON.parse((await s.prepare()).body);assert.equal(s.writes,0);assert.equal((await call(s.router,'/auth/workspace/tasks/create-save',{method:'POST',headers:s.headers,body:{reviewId:review.reviewId,approved:false}})).status,409);const results=await Promise.all([s.save(review.reviewId),s.save(review.reviewId)]);assert.deepEqual(results.map(row=>row.status).sort(),[200,409]);assert.equal(s.writes,1);assert.equal(s.row.payload.done,false);});
test('cross-origin and malformed creation proposals cannot write records',async t=>{const s=await creationSetup(t);assert.equal((await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:{...s.headers,origin:'https://other.test'},body:{title:'Fictional',day:'2026-11-09',section:'Home'}})).status,403);assert.equal((await call(s.router,'/auth/workspace/tasks/create-review',{method:'POST',headers:s.headers,body:{title:'Fictional',day:'2026-11-09',section:'Home',owner_id:owner}})).status,409);assert.equal(s.writes,0);});
test('logout or a fresh list invalidates task creation reviews before insertion',async t=>{for(const mode of ['logout','refresh']){const s=await creationSetup(t),review=JSON.parse((await s.prepare()).body);if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.notEqual((await s.save(review.reviewId)).status,200);assert.equal(s.writes,0);}});
test('lost task insertion acknowledgement consumes review and never retries insertion',async t=>{const s=await creationSetup(t),review=JSON.parse((await s.prepare()).body);s.api.addFictionalTask=async()=>{s.writes++;throw Error('Lost acknowledgement');};const result=await s.save(review.reviewId);assert.equal(result.status,503);assert.match(result.body,/may have completed/);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.writes,1);});

async function taskEditSetup(t,options={}){const s=await setup(t,{allowBriefRead:true,allowTaskEdit:true,...options});s.writes=0;s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Home',item_type:'task',version:1,deleted_at:null,created_at:'2026-11-09T12:00:00Z',payload:{fictional:true,title:'Fictional editable task',day:'2000-01-01',done:false,subtasks:[{title:'Preserve',done:true}]}};s.api.listPrivateBriefRecords=async()=>[structuredClone(s.row)];s.api.getPrivateTask=async()=>[structuredClone(s.row)];s.api.updatePrivateTask=async(_token,record,_owner,payload,section)=>{s.writes++;if(record.version!==s.row.version)return[];s.row={...s.row,payload:structuredClone(payload),section,version:s.row.version+1};return[structuredClone(s.row)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body);s.token=brief.dueTasks[0].editToken;s.prepare=()=>call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:'Edited fictional task',day:'2000-01-02',section:'Work'}});s.save=reviewId=>call(s.router,'/auth/workspace/tasks/edit-save',{method:'POST',headers:s.headers,body:{reviewId,approved:true}});return s;}
test('task edits are default-off; review is non-writing and one approved edit preserves other fields',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/tasks/edit-save',{method:'POST',headers:off.headers})).status,404);const s=await taskEditSetup(t),view=JSON.parse((await s.prepare()).body);assert.equal(s.writes,0);const results=await Promise.all([s.save(view.reviewId),s.save(view.reviewId)]);assert.deepEqual(results.map(row=>row.status).sort(),[200,409]);assert.equal(s.writes,1);assert.equal(s.row.payload.subtasks[0].done,true);assert.equal(s.row.payload.done,false);assert.equal(s.row.section,'Work');});
test('task edit proposals cannot inject completion, owner, payload or other fields',async t=>{const s=await taskEditSetup(t);for(const extra of [{done:true},{owner_id:owner},{payload:{}},{id:s.row.id}])assert.equal((await call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:'Fictional',day:'2000-01-02',section:'Home',...extra}})).status,409);assert.equal(s.writes,0);});
test('sign-out during a task edit preflight prevents the mutation',async t=>{const s=await taskEditSetup(t),view=JSON.parse((await s.prepare()).body);let release;s.api.getPrivateTask=()=>new Promise(resolve=>release=resolve);const pending=s.save(view.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);assert.equal((await pending).status,409);assert.equal(s.writes,0);});
test('task edits with lost acknowledgement cannot replay, and refresh invalidates the selection',async t=>{const s=await taskEditSetup(t),view=JSON.parse((await s.prepare()).body);s.api.updatePrivateTask=async()=>{s.writes++;throw Error('Lost acknowledgement');};assert.equal((await s.save(view.reviewId)).status,503);assert.equal((await s.save(view.reviewId)).status,409);await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal((await s.prepare()).status,409);assert.equal(s.writes,1);});

test('editing a task invalidates its previously displayed completion review, and fresh completion preserves edits',async t=>{const s=await taskEditSetup(t,{allowTaskCompletion:true});let brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body);s.token=brief.dueTasks[0].editToken;const oldCompletion=brief.dueTasks[0].completionToken,view=JSON.parse((await s.prepare()).body);assert.equal((await s.save(view.reviewId)).status,200);assert.equal((await call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:oldCompletion}})).status,409);brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body);const review=await call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:brief.dueTasks[0].completionToken}});s.api.completePrivateTask=async(_token,record,_owner,payload)=>{if(record.version!==s.row.version)return[];s.row={...s.row,payload:structuredClone(payload),version:s.row.version+1};return[structuredClone(s.row)];};assert.equal((await call(s.router,'/auth/workspace/tasks/complete',{method:'POST',headers:s.headers,body:{reviewId:JSON.parse(review.body).reviewId,approved:true}})).status,200);assert.equal(s.row.section,'Work');assert.equal(s.row.payload.day,'2000-01-02');assert.equal(s.row.payload.subtasks[0].done,true);assert.equal(s.row.payload.done,true);});

test('passive HTTP checks verify sign-in without app reads, bootstrap cookies or idle extension',async t=>{let clock=1;const s=await setup(t,{now:()=>clock}),anonymous=await call(s.router,'/auth/workspace/check');assert.equal(anonymous.status,401);assert.equal(anonymous.headers['Set-Cookie'],undefined);const login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body);clock=100001;const checked=await call(s.router,'/auth/workspace/check',{headers:{cookie:s.cookie}});assert.equal(checked.status,200);assert.equal(JSON.parse(checked.body).expiresAt,login.expiresAt);assert.equal(checked.headers['Set-Cookie'],undefined);assert.doesNotMatch(checked.body,/FICTIONAL_|sessionId|accessToken|refreshToken/);s.state.active=false;const revoked=await call(s.router,'/auth/workspace/check',{headers:{cookie:s.cookie}});assert.equal(revoked.status,401);assert.match(revoked.headers['Set-Cookie'],/Max-Age=0/);});

