test('search does not invalidate existing Brief task edit handles',async t=>{const s=await actionableTaskSearch(t),original=s.token;await s.search();s.token=original;assert.equal((await s.prepare()).status,200);});
test('later searches invalidate older task actions and pending completion reviews',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];let release;s.api.getPrivateTask=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:row.completionToken}});while(!release)await new Promise(resolve=>setImmediate(resolve));await s.search();release([s.row]);assert.equal((await pending).status,409);s.token=row.editToken;assert.equal((await s.prepare()).status,409);assert.equal(s.writes,0);});
test('search cannot invalidate a task edit already being saved',async t=>{const s=await actionableTaskSearch(t),row=JSON.parse((await s.search()).body).results[0];s.token=row.editToken;const review=JSON.parse((await s.prepare()).body);let release,calls=0;const read=s.api.getPrivateTask;s.api.getPrivateTask=(...args)=>++calls===1?new Promise(resolve=>release=resolve):read(...args);const pending=s.save(review.reviewId);while(!release)await new Promise(resolve=>setImmediate(resolve));assert.equal((await s.search()).status,409);release([structuredClone(s.row)]);assert.equal((await pending).status,200);assert.equal(s.writes,1);});

async function appearanceSetup(t){const s=await setup(t,{allowBriefRead:true,allowAppearance:true});s.appearanceReads=0;s.row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',version:1,deleted_at:null,...makeBriefPreferencesRecord({palette:'coastal',density:'compact'},owner)};s.row.payload.secret='NEVER_RETURN_APPEARANCE';s.api.listPrivateAppearance=async()=>{s.appearanceReads++;return[s.row];};s.brief=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});return s;}
test('saved appearance is opt-in and returned only after verified login without unrelated settings',async t=>{const s=await appearanceSetup(t);assert.equal((await s.brief()).status,401);assert.equal(s.appearanceReads,0);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const result=await s.brief();assert.equal(result.status,200);assert.equal(JSON.parse(result.body).appearance.palette,'coastal');assert.equal(JSON.parse(result.body).appearance.readOnly,true);assert.equal(s.appearanceReads,1);assert.doesNotMatch(result.body,/NEVER_RETURN_APPEARANCE|bbbbbbbb|quietHours|navigation/);});
test('appearance read outage uses an explicit default without blocking verified Brief records',async t=>{const s=await appearanceSetup(t);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.api.listPrivateAppearance=async()=>{throw Error('Fictional unavailable appearance');};const result=await s.brief();assert.equal(result.status,200);assert.equal(JSON.parse(result.body).appearance.available,false);assert.equal(JSON.parse(result.body).appearance.palette,'neutral');});
test('foreign appearance or sign-out during its read cannot leak display settings',async t=>{for(const mode of ['foreign','logout']){const s=await appearanceSetup(t);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});let release;s.api.listPrivateAppearance=()=>new Promise(resolve=>release=resolve);const pending=s.brief();while(!release)await new Promise(resolve=>setImmediate(resolve));if(mode==='logout')await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});else s.row.owner_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';release([s.row]);const result=await pending;assert.equal(result.status,503);assert.doesNotMatch(result.body,/coastal|compact|bbbbbbbb|NEVER_RETURN/);}});

async function displayOnlySettings(t){const s=await writeSetup(t,{allowBriefRead:true,allowAppearance:true,appearanceOnly:true});s.reviewDisplay=async changes=>{const current=JSON.parse((await s.latest()).body);return call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag:current.baseTag,changes:changes||{palette:'blush',density:'compact'}}});};return s;}
test('appearance-only settings expose two display fields and preserve every other preference on reviewed save',async t=>{const s=await displayOnlySettings(t);delete s.state.current.payload.quietHours;const initial=JSON.parse((await s.latest()).body);assert.deepEqual(Object.keys(initial.preferences).sort(),['density','palette']);assert.doesNotMatch(JSON.stringify(initial),/navigation|quietHours|hideAmounts|futureField/);const original=structuredClone(s.state.current.payload),review=JSON.parse((await s.reviewDisplay()).body);assert.equal(s.state.writes,0);const saved=await s.save(review.reviewId);assert.equal(saved.status,200);assert.deepEqual(Object.keys(JSON.parse(saved.body).preferences).sort(),['density','palette']);assert.equal(s.state.current.payload.hideAmounts,original.hideAmounts);assert.equal(s.state.current.payload.futureField,original.futureField);assert.deepEqual(s.state.current.payload.navigation,original.navigation);assert.deepEqual(s.state.current.payload.sources,original.sources);assert.equal(Object.hasOwn(s.state.current.payload,'quietHours'),false);});
test('appearance-only reviews reject hidden preference changes and unchanged values never write',async t=>{const s=await displayOnlySettings(t);assert.equal((await s.reviewDisplay({palette:'coastal',density:'compact',hideAmounts:false})).status,409);const p=JSON.parse((await s.latest()).body).preferences,result=await s.reviewDisplay(p);assert.equal(JSON.parse(result.body).noChanges,true);assert.equal(s.state.writes,0);});
test('discarding a settings review invalidates it on the server before another save',async t=>{const s=await displayOnlySettings(t),review=JSON.parse((await s.reviewDisplay()).body);assert.equal((await call(s.router,'/auth/workspace/preferences/cancel',{method:'POST',headers:s.headers})).status,200);assert.equal((await s.save(review.reviewId)).status,409);assert.equal(s.state.writes,0);});
test('discard during pending appearance review suppresses its late review token',async t=>{const s=await displayOnlySettings(t),baseTag=JSON.parse((await s.latest()).body).baseTag;let release;s.api.listBriefPreferences=()=>new Promise(resolve=>release=resolve);const pending=call(s.router,'/auth/workspace/preferences/review',{method:'POST',headers:s.headers,body:{baseTag,changes:{palette:'blush',density:'compact'}}});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/preferences/cancel',{method:'POST',headers:s.headers});release([s.state.current]);assert.equal((await pending).status,409);assert.equal(s.state.writes,0);});

test('separately enabled reopening is private, approved, one-use and retains subtasks',async t=>{const s=await setup(t,{allowBriefRead:true,allowTaskCompletion:true,allowTaskReopen:true});let row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Home',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional completed task',day:'2026-11-09',done:true,status:'Completed',subtasks:[{title:'Preserve',done:true}]}},writes=0;s.api.listPrivateBriefRecords=async()=>[structuredClone(row)];s.api.getPrivateTask=async()=>[structuredClone(row)];s.api.reopenPrivateTask=async(_token,record,_owner,payload)=>{writes++;assert.equal(record.version,row.version);row={...row,payload:structuredClone(payload),version:row.version+1};return[structuredClone(row)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),token=brief.completedTasks[0].reopenToken;assert.match(token,/^[A-Za-z0-9_-]{43}$/);const review=JSON.parse((await call(s.router,'/auth/workspace/tasks/review',{method:'POST',headers:s.headers,body:{completionToken:token}})).body);assert.equal(review.reopening,true);assert.equal(writes,0);const save=()=>call(s.router,'/auth/workspace/tasks/complete',{method:'POST',headers:s.headers,body:{reviewId:review.reviewId,approved:true}});assert.equal(JSON.parse((await save()).body).reopened,true);assert.equal((await save()).status,409);assert.equal(writes,1);assert.equal(row.payload.done,false);assert.deepEqual(row.payload.subtasks,[{title:'Preserve',done:true}]);});

test('fragmented UTF-8 request chunks preserve fictional Unicode login and note text exactly',async t=>{const s=await setup(t);let received;s.api.signIn=async(email,password)=>{received={email,password};return{accessToken:'FICTIONAL',refreshToken:'FICTIONAL_REFRESH',expiresAt:Date.now()+3600000};};const values={email:'fictional@example.test',password:'Fictional-é-学-🔒'},bytes=Buffer.from(JSON.stringify(values));await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,bodyReader:async function*(){for(const byte of bytes)yield Buffer.from([byte]);}});assert.deepEqual(received,values);const n=await noteCreationSetup(t),note={title:'Fictional café 学 🗓',body:'Fictional text — naïve 中文 🔒'},encoded=Buffer.from(JSON.stringify(note)),result=await call(n.router,'/auth/workspace/notes/create-review',{method:'POST',headers:n.headers,bodyReader:async function*(){for(const byte of encoded)yield Buffer.from([byte]);}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).title,note.title);assert.equal(JSON.parse(result.body).body,note.body);assert.equal(n.writes,0);});
test('new-note review accepts the documented text limit even when JSON escaping exceeds four kilobytes',async t=>{const s=await noteCreationSetup(t),body={title:'Fictional escaped text',body:'\u0001'.repeat(1000)};assert.ok(Buffer.byteLength(JSON.stringify(body))>4096);const reviewed=await call(s.router,'/auth/workspace/notes/create-review',{method:'POST',headers:s.headers,body});assert.equal(reviewed.status,200);assert.equal(JSON.parse(reviewed.body).body,body.body);assert.equal(s.writes,0);});

test('malformed UTF-8 and oversized login requests never reach authentication',async t=>{for(const mode of ['invalid','oversized']){const s=await setup(t),bytes=mode==='invalid'?Buffer.concat([Buffer.from('{"email":"fictional@example.test","password":"'),Buffer.from([0xff]),Buffer.from('"}')]):Buffer.from(JSON.stringify({email:'fictional@example.test',password:'x'.repeat(4096)})),result=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,bodyReader:async function*(){yield bytes;}});assert.notEqual(result.status,200);assert.equal(s.state.logins,0);assert.doesNotMatch(result.body,/fictional@example|password|\ufffd/);}});

test('selected task route protects context and returns details only after an explicit read',async t=>{const s=await setup(t,{allowBriefRead:true,allowTaskRead:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Work',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional selected task',day:'2026-11-09',done:false,description:'Fictional detail',subtasks:[]}};let reads=0;s.api.listPrivateBriefRecords=async()=>[row];s.api.getPrivateTaskDetails=async()=>{reads++;return[row];};const login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body),headers={...s.headers,'x-cc-csrf':login.csrf};const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),token=[...brief.dueTasks,...brief.upcomingTasks][0].taskReadToken;assert.equal(reads,0);assert.doesNotMatch(JSON.stringify(brief),/Fictional detail/);const post=(h,body)=>call(s.router,'/auth/workspace/tasks/read',{method:'POST',headers:h,body});assert.equal((await post({...headers,origin:'https://evil.test'},{taskReadToken:token})).status,403);assert.equal((await post(headers,{taskReadToken:'unknown'})).status,409);assert.equal(reads,0);const result=await post(headers,{taskReadToken:token});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).description,'Fictional detail');assert.doesNotMatch(result.body,/bbbbbbbb|FICTIONAL_ACCESS/);await call(s.router,'/auth/workspace/logout',{method:'POST',headers});assert.notEqual((await post(headers,{taskReadToken:token})).status,200);assert.equal(reads,1);});

test('search paging retires earlier page handles, keeps Brief handles and rejects invalid offsets before reads',async t=>{const s=await setup(t,{allowBriefRead:true,allowSearch:true,allowTaskRead:true}),rows=Array.from({length:51},(_,i)=>({id:'00000000-0000-4000-8000-'+String(i+1).padStart(12,'0'),owner_id:owner,household_id:null,visibility:'private',section:'Work',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional '+String(i).padStart(3,'0'),day:'2026-11-09',done:false,description:'Fictional details',subtasks:[]}}));let lists=0;s.api.listPrivateBriefRecords=async()=>{lists++;return rows;};s.api.getPrivateTaskDetails=async(_access,id)=>rows.filter(row=>row.id===id);const login=JSON.parse((await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}})).body),headers={...s.headers,'x-cc-csrf':login.csrf};const brief=JSON.parse((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).body),briefToken=brief.dueTasks[0].taskReadToken,fields={query:'',type:'task',section:'all',status:'all'};const post=(path,body)=>call(s.router,'/auth/workspace/'+path,{method:'POST',headers,body});const first=JSON.parse((await post('search',fields)).body),last=JSON.parse((await post('search',{...fields,offset:50})).body);assert.equal(first.results.length,50);assert.equal(last.offset,50);assert.equal(last.results.length,1);assert.equal((await post('tasks/read',{taskReadToken:first.results[0].taskReadToken})).status,409);assert.equal((await post('tasks/read',{taskReadToken:last.results[0].taskReadToken})).status,200);assert.equal((await post('tasks/read',{taskReadToken:briefToken})).status,200);const count=lists;assert.equal((await post('search',{...fields,offset:1})).status,409);assert.equal(lists,count);});

test('event details are suppressed if their selection changes or expires during final session verification',async t=>{for(const mode of ['refresh','expiry']){let stamp=Date.now();const s=await setup(t,{now:()=>stamp,allowBriefRead:true,allowEventCreate:true,allowEventEdit:true,allowEventDetails:true}),row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Calendar',item_type:'event',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional event',day:'2099-12-31',time:'09:30',location:'PRIVATE_FICTIONAL_LOCATION',description:'PRIVATE_FICTIONAL_EVENT_DETAILS'}};s.api.listPrivateBriefRecords=async()=>[structuredClone(row)];await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});const list=()=>call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}}),token=JSON.parse((await list()).body).upcomingEvents[0].eventEditToken;let release,gate=false;const verify=s.api.isSessionActive;s.api.getPrivateEvent=async()=>{gate=true;return[structuredClone(row)];};s.api.isSessionActive=async(...args)=>gate?new Promise(resolve=>release=resolve):verify(...args);const pending=call(s.router,'/auth/workspace/events/edit-read',{method:'POST',headers:s.headers,body:{editToken:token}});for(let attempt=0;!release&&attempt<100;attempt++)await new Promise(resolve=>setImmediate(resolve));if(!release){const early=await pending;assert.fail('Event read ended before verification: '+early.status);}gate=false;const refreshing=mode==='refresh'?list():null;if(mode==='expiry')stamp+=300001;release(true);if(refreshing)await refreshing;const response=await pending;assert.equal(response.status,409);assert.doesNotMatch(response.body,/PRIVATE_FICTIONAL_LOCATION|PRIVATE_FICTIONAL_EVENT_DETAILS/);}});

test('recovery routes are default-off and require explicit sparse APIs',async t=>{const s=await setup(t);assert.equal((await call(s.router,'/auth/workspace/records/deleted',{method:'POST',headers:s.headers})).status,404);assert.throws(()=>createPrivateSessionHttp({origin,api:{},allowRecentlyDeleted:true}));});
test('reviewed removal/restoration uses opaque selections, preserves bodies and requires approval',async t=>{const s=await setup(t,{allowBriefRead:true,allowRecentlyDeleted:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional recovery <script>',body:'Never return this body'}},copy=()=>structuredClone(row);let writes=0;s.api.listPrivateBriefRecords=async()=>row.deleted_at?[]:[copy()];s.api.getPrivateRecordState=async()=>[copy()];s.api.listPrivateDeletedRecords=async()=>row.deleted_at?[copy()]:[];s.api.setPrivateRecordDeletedAt=async(_token,record,_owner,date)=>{assert.equal(record.version,row.version);row.version++;row.deleted_at=date;writes++;return[copy()];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}});assert.equal(login.status,200);const headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf},post=(path,body={})=>call(s.router,'/auth/workspace/records/'+path,{method:'POST',headers,body});const brief=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(brief.status,200);const token=JSON.parse(brief.body).notes[0].recordToken;assert.match(token,/^[A-Za-z0-9_-]{43}$/);const review=await post('review',{recordToken:token});assert.equal(review.status,200);assert.doesNotMatch(review.body,/Never return|bbbbbbbb|accessToken/);assert.equal(writes,0);const reviewId=JSON.parse(review.body).reviewId;assert.equal((await post('save',{reviewId,approved:false})).status,409);assert.equal(writes,0);assert.equal((await post('save',{reviewId,approved:true})).status,200);assert.equal(writes,1);assert.equal((await post('save',{reviewId,approved:true})).status,409);const deleted=await post('deleted');assert.equal(deleted.status,200);const record=JSON.parse(deleted.body).records[0];const restore=await post('review',{recordToken:record.recordToken});assert.equal(JSON.parse(restore.body).restoring,true);assert.equal(writes,1);assert.equal((await post('save',{reviewId:JSON.parse(restore.body).reviewId,approved:true})).status,200);assert.equal(writes,2);assert.equal(row.deleted_at,null);assert.equal(row.payload.body,'Never return this body');assert.equal((await post('review',{recordToken:token,recordId:row.id})).status,409);assert.equal((await post('deleted',{offset:1})).status,409);});

test('an in-flight recovery save blocks duplicate writes and Brief refresh until acknowledgement',async t=>{const s=await setup(t,{allowBriefRead:true,allowRecentlyDeleted:true});const row={id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'note',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional lock check'}},copy=()=>structuredClone(row);s.api.listPrivateBriefRecords=async()=>row.deleted_at?[]:[copy()];s.api.getPrivateRecordState=async()=>[copy()];let release;s.api.setPrivateRecordDeletedAt=async(_token,_record,_owner,date)=>new Promise(resolve=>{release=()=>{row.deleted_at=date;row.version++;resolve([copy()]);};});const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf},post=(path,body={})=>call(s.router,'/auth/workspace/records/'+path,{method:'POST',headers,body});const brief=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}}),review=await post('review',{recordToken:JSON.parse(brief.body).notes[0].recordToken}),reviewId=JSON.parse(review.body).reviewId;const pending=post('save',{reviewId,approved:true});while(!release)await new Promise(resolve=>setImmediate(resolve));assert.equal((await post('save',{reviewId,approved:false})).status,409);assert.equal((await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}})).status,409);release();assert.equal((await pending).status,200);assert.equal(row.version,2);});

test('date browsing is default-off and rejects malformed dates or missing CSRF before record reads',async t=>{const off=await setup(t,{allowBriefRead:true});assert.equal((await call(off.router,'/auth/workspace/brief-date',{method:'POST',headers:off.headers,body:{day:'2026-11-08'}})).status,404);const s=await setup(t,{allowBriefRead:true,allowBriefDates:true,allowTaskCompletion:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf};for(const day of ['2026-02-29',null,['2026-11-09'],'2101-01-01'])assert.equal((await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers,body:{day}})).status,409);assert.equal((await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers:{...headers,'x-cc-csrf':'invalid'},body:{day:'2026-11-08'}})).status,403);assert.equal(reads,0);const result=await call(s.router,'/auth/workspace/brief-date',{method:'POST',headers,body:{day:'2026-11-08'}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).day,'2026-11-08');assert.equal(JSON.parse(result.body).selectedDate,true);assert.equal(reads,1);});

test('priority labels pass through task-action Briefs and priority filters reject invalid input before reads',async t=>{const s=await setup(t,{allowBriefRead:true,allowSearch:true,allowTaskPriorityLists:true,allowTaskCompletion:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Work',item_type:'task',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional priority list task',day:'2000-01-01',done:false,priority:'High'}}];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf};const brief=await call(s.router,'/auth/workspace/brief',{headers:{cookie:s.cookie}});assert.equal(brief.status,200);assert.equal(JSON.parse(brief.body).dueTasks[0].priority,'High');assert.equal(JSON.parse(brief.body).taskCompletionAvailable,true);const values={query:'',type:'task',section:'all',status:'all',priority:'High'},before=reads;assert.equal((await call(s.router,'/auth/workspace/search',{method:'POST',headers,body:{...values,priority:null}})).status,409);assert.equal(reads,before);const search=await call(s.router,'/auth/workspace/search',{method:'POST',headers,body:values});assert.equal(search.status,200);assert.equal(JSON.parse(search.body).results[0].priority,'High');assert.equal(JSON.parse(search.body).priority,'High');});

test('date-filter routes reject invalid bounds before reads and return validated inclusive dates',async t=>{const s=await setup(t,{allowBriefRead:true,allowSearch:true,allowSearchDates:true});let reads=0;s.api.listPrivateBriefRecords=async()=>{reads++;return[{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Calendar',item_type:'event',version:1,deleted_at:null,payload:{fictional:true,title:'Fictional spanning date filter',day:'2026-11-08',time:'23:00',end_day:'2026-11-09',end_time:'01:00'}}];};const login=await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fixture',password:'fixture'}}),headers={...s.headers,'x-cc-csrf':JSON.parse(login.body).csrf},values={query:'',type:'event',section:'all',dateFrom:'2026-11-09',dateTo:'2026-11-09'};assert.equal((await call(s.router,'/auth/workspace/search',{method:'POST',headers,body:{...values,dateFrom:'2026-11-10'}})).status,409);assert.equal(reads,0);const response=await call(s.router,'/auth/workspace/search',{method:'POST',headers,body:values});assert.equal(response.status,200);const result=JSON.parse(response.body);assert.equal(result.matchCount,1);assert.equal(result.dateFrom,'2026-11-09');assert.equal(result.results[0].day,'2026-11-08');assert.equal(result.dateRangeUnavailableRecords,0);});

 test('Calendar pause requires authenticated protected requests and binds to the signed-in owner',async t=>{let pauses=[];const io={mode:'on-open',maxEvents:250,selectionForOwner:async()=>{throw Error('No reads expected');},readCalendarWindow:async()=>{throw Error('No native reads expected');},pause:async id=>{pauses.push(id);return{paused:true};}},s=await setup(t,{macCalendarOpenPreviewIO:io});const path='/auth/workspace/calendar-source/pause';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const headers of [{...s.headers,origin:'https://foreign.test'},{...s.headers,'x-cc-csrf':'invalid'}])assert.equal((await call(s.router,path,{method:'POST',headers})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:'foreign'}})).status,409);assert.deepEqual(pauses,[]);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,200);assert.deepEqual(pauses,[owner]);});

test('date-only task review and save preserve description, priority, checklist and unknown extension fields',async t=>{const s=await taskEditSetup(t);Object.assign(s.row.payload,{description:'Fictional long description',priority:'High',fixtureExtension:{keep:true}});const original=structuredClone(s.row.payload);const reviewed=await call(s.router,'/auth/workspace/tasks/edit-review',{method:'POST',headers:s.headers,body:{editToken:s.token,title:s.row.payload.title,day:'2000-01-03',section:s.row.section}});assert.equal(reviewed.status,200);assert.equal(s.writes,0);assert.doesNotMatch(reviewed.body,/Fictional long description|fixtureExtension/);const id=JSON.parse(reviewed.body).reviewId;const saved=await Promise.all([s.save(id),s.save(id)]);assert.deepEqual(saved.map(r=>r.status).sort(),[200,409]);assert.equal(s.writes,1);assert.deepEqual({...s.row.payload,day:original.day},original);});

test('copied note HTTP review preserves whitespace only under its explicit scope and inserts no copy-control metadata',async t=>{const body='\n  Fictional copy.\n\n',off=await noteCreationSetup(t);assert.equal((await call(off.router,'/auth/workspace/notes/create-review',{method:'POST',headers:off.headers,body:{title:'Fictional copy',body,preserveWhitespace:true}})).status,409);assert.equal(off.writes,0);const s=await noteCreationSetup(t,{allowNoteCopy:true}),review=await call(s.router,'/auth/workspace/notes/create-review',{method:'POST',headers:s.headers,body:{title:'Fictional copy',body,preserveWhitespace:true}});assert.equal(review.status,200);assert.equal(JSON.parse(review.body).body,body);assert.equal(s.writes,0);assert.equal((await s.save(JSON.parse(review.body).reviewId)).status,200);assert.equal(s.row.payload.body,body);assert.equal(Object.hasOwn(s.row.payload,'preserveWhitespace'),false);});

function savedMailRow(){return{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:owner,household_id:null,visibility:'private',section:'Personal Life',item_type:'provider_email',origin:'google_readonly',deleted_at:null,created_at:'2026-11-07T18:00:00Z',provider:'gmail',fictional:false,subject:'Fictional mail subject',sender:'Fictional sender',received_at:'2026-11-06T15:00:00Z'};}
test('saved-mail route requires explicit scope, sign-in, empty body and CSRF before metadata reads',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/saved-mail',{method:'POST',headers:off.headers})).status,404);const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});let reads=0;s.api.listSavedMailMetadata=async(_token,id)=>{assert.equal(id,owner);reads++;return[savedMailRow()];};const path='/auth/workspace/saved-mail';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'}})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:owner}})).status,409);assert.equal(reads,0);const result=await call(s.router,path,{method:'POST',headers:s.headers});assert.equal(result.status,200);assert.equal(reads,1);assert.equal(JSON.parse(result.body).records[0].subject,'Fictional mail subject');assert.doesNotMatch(result.body,/bbbbbbbb|owner_id|accessToken|refreshToken/);});
test('saved-mail foreign metadata and late signed-out responses are withheld completely',async t=>{for(const mode of ['foreign','logout']){const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});let release;s.api.listSavedMailMetadata=()=>new Promise(r=>release=r);const pending=call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers});while(!release)await new Promise(r=>setImmediate(r));const row=savedMailRow();if(mode==='foreign')row.owner_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';else await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([row]);const result=await pending;assert.notEqual(result.status,200);assert.doesNotMatch(result.body,/Fictional mail subject|Fictional sender/);}});
test('saved-mail pages accept only bounded five-step offsets before issuing sparse reads',async t=>{const s=await setup(t,{allowBriefRead:true,allowSavedMailRead:true});let reads=0,seenOffset;s.api.listSavedMailMetadata=async(_token,id,options)=>{assert.equal(id,owner);reads++;seenOffset=options.offset;return[savedMailRow()];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const offset of [-5,1,500,null,'5'])assert.equal((await call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers,body:{offset}})).status,409);assert.equal(reads,0);const result=await call(s.router,'/auth/workspace/saved-mail',{method:'POST',headers:s.headers,body:{offset:5}});assert.equal(result.status,200);assert.equal(seenOffset,5);assert.equal(JSON.parse(result.body).offset,5);});

test('saved accounts require explicit scope, active sign-in, CSRF and empty input, and suppress a signed-out late response',async t=>{const off=await setup(t),path='/auth/workspace/saved-finance-accounts';assert.equal((await call(off.router,path,{method:'POST',headers:off.headers})).status,404);let reads=0,release;const s=await setup(t,{allowBriefRead:true,allowSavedFinanceRead:true,savedFinanceReader:async actor=>{reads++;assert.equal(actor.ownerId,owner);return new Promise(r=>release=r);}});assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'}})).status,403);assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body:{ownerId:owner}})).status,409);assert.equal(reads,0);const pending=call(s.router,path,{method:'POST',headers:s.headers});while(!release)await new Promise(r=>setImmediate(r));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([savedAccountRow()]);const result=await pending;assert.notEqual(result.status,200);assert.doesNotMatch(result.body,/Fictional checking|123456|ACCOUNT_ID/);});

test('saved transactions require their own scope and bounded input before a reader can run',async t=>{let reads=0;const s=await setup(t,{allowBriefRead:true,allowSavedFinanceRead:true,savedFinanceReader:async()=>[],allowSavedTransactionsRead:true,savedTransactionReader:async(actor,{offset})=>{reads++;assert.equal(actor.ownerId,owner);assert.equal(offset,20);return[];}}),path='/auth/workspace/saved-finance-transactions';assert.equal((await call(s.router,path,{method:'POST',headers:s.headers})).status,401);await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});for(const body of [{ownerId:owner},{offset:1},{offset:null},{offset:500}])assert.equal((await call(s.router,path,{method:'POST',headers:s.headers,body})).status,409);assert.equal((await call(s.router,path,{method:'POST',headers:{...s.headers,'x-cc-csrf':'bad'},body:{offset:20}})).status,403);assert.equal(reads,0);const result=await call(s.router,path,{method:'POST',headers:s.headers,body:{offset:20}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).offset,20);assert.equal(reads,1);});

async function projectSetup(t){const s=await setup(t,{allowProjects:true});s.writes=0;s.row=null;s.api.listPrivateProjects=async()=>s.row?[structuredClone(s.row)]:[];s.api.getPrivateProject=async()=>s.row?[structuredClone(s.row)]:[];s.api.addPrivateProject=async(_token,r)=>{s.writes++;s.row={...structuredClone(r),version:1,deleted_at:null,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};return[structuredClone(s.row)];};s.api.updatePrivateProject=async(_token,r,_owner,p)=>{s.writes++;if(s.row.version!==r.version)return[];s.row={...s.row,payload:p.payload,section:p.section,version:r.version+1};return[structuredClone(s.row)];};await call(s.router,'/auth/workspace/login',{method:'POST',headers:s.headers,body:{email:'fictional@example.test',password:'fixture'}});s.project=(action,body={})=>call(s.router,'/auth/workspace/projects/'+action,{method:'POST',headers:s.headers,body});s.fields={title:'Fictional project',description:'PRIVATE_PROJECT_BODY',section:'Work',status:'Active'};await s.project('list');return s;}
test('private project HTTP is opt-in, protected, reviewed and consumes approval once',async t=>{const off=await setup(t);assert.equal((await call(off.router,'/auth/workspace/projects/list',{method:'POST',headers:off.headers})).status,404);const s=await projectSetup(t);for(const headers of [{...s.headers,origin:'https://other.test'},{...s.headers,'x-cc-csrf':'wrong'}])assert.equal((await call(s.router,'/auth/workspace/projects/review',{method:'POST',headers,body:{action:'create',fields:s.fields}})).status,403);assert.equal((await s.project('review',{action:'create',fields:s.fields,owner_id:owner})).status,409);const review=await s.project('review',{action:'create',fields:s.fields});assert.equal(review.status,200);assert.equal(s.writes,0);const id=JSON.parse(review.body).reviewId;assert.equal((await s.project('save',{reviewId:id,approved:false})).status,409);const results=await Promise.all([s.project('save',{reviewId:id,approved:true}),s.project('save',{reviewId:id,approved:true})]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal(s.writes,1);const list=await s.project('list');assert.doesNotMatch(list.body,/PRIVATE_PROJECT_BODY|owner_id/);const read=await s.project('read',{projectToken:JSON.parse(list.body).projects[0].projectToken});assert.equal(JSON.parse(read.body).description,'PRIVATE_PROJECT_BODY');});
test('project HTTP withholds late details after logout',async t=>{const s=await projectSetup(t);let r=JSON.parse((await s.project('review',{action:'create',fields:s.fields})).body);await s.project('save',{reviewId:r.reviewId,approved:true});const list=JSON.parse((await s.project('list')).body);let release;s.api.getPrivateProject=()=>new Promise(resolve=>release=resolve);const pending=s.project('read',{projectToken:list.projects[0].projectToken});while(!release)await new Promise(resolve=>setImmediate(resolve));await call(s.router,'/auth/workspace/logout',{method:'POST',headers:s.headers});release([s.row]);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_PROJECT_BODY/);});
test('cancelling projects during final session verification suppresses an older project review',async t=>{const s=await projectSetup(t);let release,gate=true;const verify=s.api.isSessionActive;let calls=0;s.api.isSessionActive=async(...args)=>{calls++;if(gate&&calls===2)return new Promise(resolve=>release=resolve);return verify(...args);};const pending=s.project('review',{action:'create',fields:s.fields});while(!release)await new Promise(resolve=>setImmediate(resolve));gate=false;assert.equal((await s.project('cancel')).status,200);release(true);const result=await pending;assert.equal(result.status,409);assert.doesNotMatch(result.body,/PRIVATE_PROJECT_BODY|reviewId/);assert.equal(s.writes,0);});

test('project review accepts the full supported description length through bounded HTTP input',async t=>{const s=await projectSetup(t),description='漢字\n'.repeat(3333)+'x';assert.equal(description.length,10000);const result=await s.project('review',{action:'create',fields:{...s.fields,description}});assert.equal(result.status,200);assert.equal(JSON.parse(result.body).description,description);assert.equal(s.writes,0);const oversized=await s.project('review',{action:'create',fields:{...s.fields,description:'x'.repeat(70000)}});assert.equal(oversized.status,409);assert.equal(s.writes,0);});
